def round_to_step(val: int, step: int) -> int:
    """将值舍入到最近的 step 倍数。"""
    return round(val / step) * step

def extract_num_cores(filename):
    pattern = r'(?P<num_cores>\d+)'
    match = re.search(pattern, filename)
    if match:
        return int(match.group('num_cores'))
    else:
        return -1

